#!/usr/bin/env bash
# Create a clean source archive for a Linux deployment.
# Secrets, runtime data and macOS metadata are deliberately excluded.
set -euo pipefail
# Exclusions do not suppress AppleDouble entries generated by macOS tar itself.
export COPYFILE_DISABLE=1

repo_root="$(cd "$(dirname "$0")/.." && pwd)"
output_path="${1:-/tmp/meeting-actions-deploy-$(date +%Y%m%d-%H%M%S).tar.gz}"
mkdir -p "$(dirname "$output_path")"

cd "$repo_root"
tar_args=(
  --exclude='./.env'
  --exclude='*/.env*'
  --exclude='*-credentials.txt'
  --exclude='*.pem'
  --exclude='*.key'
  --exclude='*.db'
  --exclude='*.sqlite'
  --exclude='*.sqlite3'
  --exclude='*.dump'
  --exclude='./.git'
  --exclude='./.git/*'
  --exclude='./.venv'
  --exclude='./.venv/*'
  --exclude='*/.venv'
  --exclude='*/.venv/*'
  --exclude='*/.pytest_cache'
  --exclude='*/.pytest_cache/*'
  --exclude='*/.ruff_cache'
  --exclude='*/.ruff_cache/*'
  --exclude='./backups'
  --exclude='./backups/*'
  --exclude='./storage/*'
  --exclude='./monitor-state/*'
  --exclude='./native-todo/*'
  --exclude='./8月会议纪要'
  --exclude='./8月会议纪要/*'
  --exclude='*/._*'
  --exclude='./._*'
  --exclude='*/.DS_Store'
  --exclude='./.DS_Store'
  --exclude='*/__pycache__'
  --exclude='*/__pycache__/*'
  --exclude='*.pyc'
  --exclude='*/node_modules'
  --exclude='./.npm-cache'
  --exclude='./.npm-cache/*'
  --exclude='*/.npm-cache'
  --exclude='*/.npm-cache/*'
  --exclude='*/node_modules/*'
  --exclude='*/dist'
  --exclude='*/dist/*'
  --exclude='*/test-results'
  --exclude='*/test-results/*'
  --exclude='*/playwright-report'
  --exclude='*/playwright-report/*'
)

tar -czf "$output_path" "${tar_args[@]}" \
  backend frontend deploy scripts docs docker-compose.yml docker-compose.app.yml \
  README.md 开发计划.md .env.example .gitignore .gitattributes

if tar -tzf "$output_path" | grep -E '(^|/)(\._[^/]*|\.DS_Store|__pycache__|[^/]+\.pyc)(/|$)' >/dev/null; then
  echo "部署包包含被禁止的缓存或 macOS 资源文件" >&2
  rm -f "$output_path"
  exit 1
fi

printf 'Deployment archive: %s\n' "$output_path"
printf 'Archive SHA-256: '
if command -v sha256sum >/dev/null 2>&1; then
  sha256sum "$output_path" | awk '{print $1}'
else
  shasum -a 256 "$output_path" | awk '{print $1}'
fi
